    /**
     * Method to retrieve the Exposure via ExposureFetchOneSummary
     * @param 	summary ExposureFetchOneSummary 
     * @return 	ExposureFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Exposure getExposure( ExposureFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "ExposureFetchOneSummary arg cannot be null" );
    	
    	Exposure entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Exposure
        	// --------------------------------------
        	CompletableFuture<Exposure> futureEntity = queryGateway.query(new FindExposureQuery( new LoadExposureFilter( summary.getExposureId() ) ), ResponseTypes.instanceOf(Exposure.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Exposure with id " + summary.getExposureId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


